import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { marked } from 'marked';

const SOURCE = 'CHANGELOG.md';
const OUTPUT = 'src/app/components/pages/changelog-page/changelog.generated.ts';

const md = readFileSync(SOURCE, 'utf8');
const html = marked.parse(md, { gfm: true, breaks: false });

const escaped = JSON.stringify(html);

const banner =
  '// Generated by scripts/generate-changelog.mjs from CHANGELOG.md.\n' +
  '// Do not edit by hand — re-run "npm run build" or the prebuild step.\n';

mkdirSync(dirname(OUTPUT), { recursive: true });
writeFileSync(OUTPUT, `${banner}export const CHANGELOG_HTML = ${escaped};\n`);

console.log(`Generated ${OUTPUT} (${escaped.length} chars).`);
